#pragma unroll
  for (int l = 0; l < N; ++l) {
    if constexpr (E == 4) wv[l] = __ldg(reinterpret_cast<const uint32_t*>(W + l * plane));
    else if constexpr (E == 2) wv[l] = __ldg(reinterpret_cast<const uint16_t*>(W + l * plane));
    else wv[l] = __ldg(W + l * plane);
  }
  uint32_t x[E][L];
#pragma unroll
  for (int e = 0; e < E; ++e) {
